interface MarkdownEditorProps {
    value: string;
    onChange: (value: string) => void;
}

export default function MarkdownEditor({ value, onChange }: MarkdownEditorProps) {
    return (
        <div className="flex flex-col h-full">
            <label htmlFor="editor" className="text-white w-fit bg-gray-700 rounded-lg rounded-b-none px-1.5 mb-1">
                Markdown Editor
            </label>
            <textarea
                id="editor"
                value={value}
                onChange={(e) => onChange(e.target.value)}
                className="w-full h-full p-4 bg-gray-800 rounded-lg text-white focus:outline-none font-mono text-sm"
                spellCheck="false"
                placeholder="Type your markdown here..."
            />
        </div>
    );
}